    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching
    if next_item_size > 0 {
        // Penalize bins that cannot fit the next item immediately
        if post_residual < next_item_size {
            score -= (next_item_size - post_residual) as f64 * seed as f64;
        }

        // Reward bins with a post_residual close to the mean residual
        let relative_residual = post_residual as f64 / mean_residual;
        score += (relative_residual - 1.0).powi(2) * seed as f64;
    } else {
        // Penalize bins that have very little space left
        if post_residual < 50 {
            score -= (50 - post_residual) as f64 * seed as f64;
        }
    }

    score
