pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = step_index as f64 / total_items as f64;
    let normalized_post_residual = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let score = -0.1 * normalized_post_residual.powi(3) * (stream_progress * 2.0 - 1.0).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 100.0 * ((bin_capacity - bin_residual) as f64 / bin_capacity as f64);

    if post_residual > 0 {
        score += 1.5;
    } else {
        score -= 0.5;
    }

    if next_item_size > 0 {
        let residual_ratio = post_residual as f64 / next_item_size as f64;
        if residual_ratio > 0.2 {
            score -= 2.0 * (residual_ratio - 0.2).ln();
        } else {
            score += 0.5 * residual_ratio.ln();
        }
    }

    score -= fitting_bins_count as f64 * 0.7;

    if mean_residual > 0.0 {
        let adjusted_mean = mean_residual / bin_capacity;
        if adjusted_mean < 1.0 {
            score += 5.0 * (1.0 - adjusted_mean).ln();
        } else {
            score -= 2.0 * (adjusted_mean - 1.0).ln();
        }
    }

    score = score * 0.98 + ((11572758976476374866) as f64) * 0.02;

    score
}

