    let score = 100.0 * ((bin_capacity - bin_residual) as f64 / bin_capacity as f64)
        + (if post_residual > 0 { 1.0 } else { 0.0 })
        - (post_residual as f64 / next_item_size as f64).ln()
        - (fitting_bins_count as f64 * 0.5)
